// Search engine: port of the Python portal (flightcore/), no Android or UI code.
// Tested on the JVM against cases generated by the portal (data/fixtures).
plugins {
    alias(libs.plugins.kotlin.multiplatform)
    alias(libs.plugins.kotlin.serialization)
}

kotlin {
    jvmToolchain(21)
    jvm()
    iosArm64()
    iosSimulatorArm64()

    compilerOptions {
        optIn.add("kotlin.time.ExperimentalTime")
    }

    sourceSets {
        commonMain.dependencies {
            implementation(libs.serialization.json)
            implementation(libs.coroutines.core)
            implementation(libs.datetime)
            implementation(libs.okio)
        }
        commonTest.dependencies {
            implementation(kotlin("test"))
            implementation(libs.coroutines.test)
        }
    }
}

tasks.withType<Test>().configureEach {
    systemProperty("fixtures", rootProject.file("data/fixtures").absolutePath)
    systemProperty("catalog", rootProject.file("data/catalog").absolutePath)
    maxHeapSize = "2g"
}
